#include "../research/NativeGlitchPattern.h"
#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <vector>
using namespace skl::native_glitch;
void check(bool c,const char* msg){if(!c){std::fprintf(stderr,"FAIL %s\n",msg);std::exit(1);}}
std::vector<float> render(const std::vector<float>& in,Settings p,int sr,int b,bool trigger=false){PatternEngine e;e.prepare(sr,1);if(trigger)e.trigger();auto x=in;for(size_t i=0;i<x.size();i+=b)e.process(x.data()+i,nullptr,int(std::min(size_t(b),x.size()-i)),p,120.);return x;}
double err(const std::vector<float>& x,const std::vector<float>& y){double e=0;for(size_t i=0;i<x.size();++i){check(std::isfinite(x[i]),"nonfinite output");e=std::max(e,std::abs(double(x[i])-y[i]));}return e;}
double peak(const std::vector<float>& x){double p=0;for(float v:x)p=std::max(p,std::abs(double(v)));return p;}
int main(int argc,char**argv){for(int sr:{44100,48000,96000,192000}){std::vector<float>x(sr*2);for(size_t i=0;i<x.size();++i)x[i]=.6f*std::sin(i*.031)+.3f*std::cos(i*.041);Settings p;p.mix=1;p.mode=0;p.wetTrimDb=0;auto classic=render(x,p,sr,257);for(int style=0;style<4;++style){p.style=style;auto a=render(x,p,sr,257),b=render(x,p,sr,63);check(err(a,b)<2e-6,"reverse partition");if(style)check(err(a,classic)>.01,"reverse style inaudible");}p.mode=1;p.style=0;p.states.fill(0);p.probability.fill(100);auto closed=render(x,p,sr,257);p.states.fill(1);auto open=render(x,p,sr,257);check(err(open,x)<2e-6&&err(closed,open)>.1,"editable pattern");p.states.fill(2);auto accented=render(x,p,sr,257);p.wetTrimDb=-1.3f;auto safe=render(x,p,sr,257);check(peak(safe)<peak(accented)&&peak(safe)<=peak(x)+1e-6,"headroom trim");p.wetTrimDb=0;p.states.fill(1);p.probability.fill(0);check(err(render(x,p,sr,257),closed)<2e-6,"zero step probability");p.probability.fill(100);p.mode=2;p.chaos=100;auto chaos=render(x,p,sr,257);check(err(chaos,render(x,p,sr,63))<2e-6,"chaos determinism");p.source=TriggerRouter::Manual;check(render(x,p,sr,257)==x,"manual not dry before trigger");check(err(render(x,p,sr,257,true),x)>.01,"manual trigger inactive");p.source=TriggerRouter::MIDI;check(err(render(x,p,sr,257,true),x)>.01,"MIDI trigger entry inactive");p.source=TriggerRouter::Sidechain;p.chaos=0;p.mode=1;p.states.fill(0);PatternEngine sideEngine;sideEngine.prepare(sr,1);auto sideOut=x;float side[257]{};for(size_t i=0;i<x.size();i+=257){int n=int(std::min(size_t(257),x.size()-i));std::fill_n(side,n,0.f);if(i==0)side[0]=1.f;sideEngine.process(sideOut.data()+i,nullptr,n,p,120.,0.,4,4,false,side);}check(err(sideOut,x)>.01,"sidechain trigger inactive");p.mix=0;check(render(x,p,sr,257,true)==x,"zero mix not dry");std::printf("%d Hz: 4 reverse styles, pattern editing, deterministic chaos, trigger and headroom passed\n",sr);}
if(argc>1){std::ifstream f(argv[1],std::ios::binary);std::vector<float>x(480000);f.read(reinterpret_cast<char*>(x.data()),x.size()*sizeof(float));x.resize(size_t(f.gcount())/sizeof(float));check(x.size()>48000,"missing vocal");Settings p;p.mode=1;p.mix=1;p.wetTrimDb=0;auto a=render(x,p,48000,257);p.wetTrimDb=-1.3f;auto b=render(x,p,48000,257);std::printf("Vocal gate peak %.2f -> %.2f dBFS with explicit wet trim\n",20*std::log10(peak(a)),20*std::log10(peak(b)));check(peak(b)<1,"vocal overload");}
}
